{$ param embed_url label="Embed URL" default="https://www.youtube.com/embed/" description="iframe src URL for the video embed." type="fileurl" $}
{$ param title label="Title" default="Video player" description="Accessible iframe title." $}

<div class="aspect-[16/9] w-full mb-8 max-w-[960px] mx-auto">
  <iframe class="w-full h-full" src="{$= embed_url $}" title="{$= title $}" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
</div>
